package com.grocery.controller; import com.grocery.entity.*; import com.grocery.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/items") public class GroceryItemController{ private final GroceryItemRepository r; public GroceryItemController(GroceryItemRepository r){this.r=r;} @GetMapping public List<GroceryItem> all(){return r.findAll();} @PostMapping public GroceryItem save(@RequestBody GroceryItem g){return r.save(g);} @GetMapping("/{id}") public GroceryItem one(@PathVariable Long id){return r.findById(id).orElseThrow();} @PutMapping("/{id}") public GroceryItem update(@PathVariable Long id,@RequestBody GroceryItem g){g.setId(id); return r.save(g);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);} }